fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since we need to check that for all i < j, arr[i] <= arr[j],
    // we can simply check consecutive elements.
    // If arr[i] > arr[i+1] for any i, then the condition fails.
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}